SELECT * FROM (SELECT e.event_id,'T:'||s.task_id case_id,e.activity,e.timestamp FROM (SELECT 'T:'||task_id||':start' event_id,'Putaway Started' activity,started_at timestamp,task_id source_key FROM warehouse_task_history WHERE started_at IS NOT NULL AND (task_code='A')) e JOIN warehouse_task_history s ON s.task_id=e.source_key WHERE s.task_id IS NOT NULL UNION ALL SELECT e.event_id,'T:'||s.task_id case_id,e.activity,e.timestamp FROM (SELECT 'T:'||task_id||':complete' event_id,'Putaway Completed' activity,completed_at timestamp,task_id source_key FROM warehouse_task_history WHERE completed_at IS NOT NULL AND (task_code='A')) e JOIN warehouse_task_history s ON s.task_id=e.source_key WHERE s.task_id IS NOT NULL UNION ALL SELECT e.event_id,'T:'||s.task_id case_id,e.activity,e.timestamp FROM (SELECT 'T:'||task_id||':start' event_id,'Picking Started' activity,started_at timestamp,task_id source_key FROM warehouse_task_history WHERE started_at IS NOT NULL AND (task_code='K')) e JOIN warehouse_task_history s ON s.task_id=e.source_key WHERE s.task_id IS NOT NULL UNION ALL SELECT e.event_id,'T:'||s.task_id case_id,e.activity,e.timestamp FROM (SELECT 'T:'||task_id||':complete' event_id,'Picking Completed' activity,completed_at timestamp,task_id source_key FROM warehouse_task_history WHERE completed_at IS NOT NULL AND (task_code='K')) e JOIN warehouse_task_history s ON s.task_id=e.source_key WHERE s.task_id IS NOT NULL UNION ALL SELECT e.event_id,'T:'||s.task_id case_id,e.activity,e.timestamp FROM (SELECT 'T:'||task_id||':start' event_id,'Packing Started' activity,started_at timestamp,task_id source_key FROM warehouse_task_history WHERE started_at IS NOT NULL AND (task_code='B')) e JOIN warehouse_task_history s ON s.task_id=e.source_key WHERE s.task_id IS NOT NULL UNION ALL SELECT e.event_id,'T:'||s.task_id case_id,e.activity,e.timestamp FROM (SELECT 'T:'||task_id||':complete' event_id,'Packing Completed' activity,completed_at timestamp,task_id source_key FROM warehouse_task_history WHERE completed_at IS NOT NULL AND (task_code='B')) e JOIN warehouse_task_history s ON s.task_id=e.source_key WHERE s.task_id IS NOT NULL) ORDER BY case_id,timestamp,event_id;
